"""This code writes the publication, teaching and miscellanea lists into index.html, publications.html and miscellanea.html

The lists are read from the json files in data/ and written between the marker comments of each page:

	<!-- research-list: generated by ... -->
	...
	<!-- end of research-list -->

so that they are part of the pages themselves instead of being built by JavaScript in the visitor's browser.
Anything written by hand between two markers is overwritten.

In a terminal, run the following command line after editing paper_data.json, course_data.json or miscellanea_data.json:

python static_list_generator.py
"""

import html
import json
import os

def parent_dir(directory):
	return os.path.dirname(directory)

PATH_TO_SCRIPT = parent_dir(os.path.realpath(__file__))
PATH_TO_WEB = parent_dir(parent_dir(PATH_TO_SCRIPT))
PATH_TO_DATA = os.path.join(PATH_TO_WEB, "data")

# list id -> data file it is built from
LIST_DATA = {
	"research-list": "paper_data.json",
	"teaching-list": "course_data.json",
	"misc-list": "miscellanea_data.json",
}

# page -> lists it shows (all the pages are at the root of the website, like the paths in the data files)
PAGE_LISTS = {
	"index.html": ["research-list", "teaching-list", "misc-list"],
	"publications.html": ["research-list"],
	"miscellanea.html": ["misc-list"],
}

# escapes a value used inside a double-quoted attribute
def attr(value):
	return html.escape(str(value), quote=True)

# the thumbnail is decorative (the title is next to it), and is only downloaded when it gets close to the screen
def thumbnail(image_path):
	return f'<img class="research-image" src="{attr(image_path)}" alt="" loading="lazy">'

# the link pills; kept on one line since spaces between the pills would be rendered
def link_pills(links):
	pills = [f'<a href="{attr(link_val)}"><span style="white-space: nowrap">{link_name}</span></a><p-inline> </p-inline>' for link_name, link_val in links.items()]
	return '<div class="links">' + ''.join(pills) + '</div>'

def research_item(paper):
	lines = [
		'<div class="research-container">',
		'\t' + thumbnail(paper["image"]),
		'\t<div>',
		f'\t\t<p class="research-title">{paper["title"]}</p>',
		f'\t\t<p class="author-list">{", ".join(paper["authors"])}<br> <i>{paper["conference"]}</i>, {paper["year"]}</p>',
	]
	if "note" in paper:
		lines.append(f'\t\t<p class="author-note">{paper["note"]}</p>')
	lines += ['\t\t' + link_pills(paper["links"]), '\t</div>', '</div>']
	return lines

def teaching_item(course):
	return [
		'<div class="teaching-container">',
		'\t<div>',
		f'\t\t<p class="teaching-title"><a href="{attr(course["link"])}">{course["title"]}</a></p>',
		f'\t\t<p class="author-list"><i>{course["venue"]}</i>, {course["terms"]}</p>',
		'\t</div>',
		'</div>',
	]

def misc_item(project):
	return [
		'<div class="research-container">',
		'\t' + thumbnail(project["image"]),
		'\t<div>',
		f'\t\t<p class="research-title">{project["title"]}</p>',
		f'\t\t<p class="author-note">{project["short_description"]}</p>',
		'\t\t' + link_pills(project["links"]),
		'\t</div>',
		'</div>',
	]

ITEM_BUILDERS = {
	"research-list": research_item,
	"teaching-list": teaching_item,
	"misc-list": misc_item,
}

# returns the page with the content between the markers of the list replaced by the lines
def fill_list(page, page_name, list_id, lines):
	start_marker, end_marker = f'<!-- {list_id}: generated', f'<!-- end of {list_id} -->'
	start = page.find(start_marker)
	end = page.find(end_marker)
	assert start != -1 and end > start, f'{page_name}: the markers "{start_marker} ... -->" and "{end_marker}" are missing or in the wrong order.'
	assert page.count(start_marker) == 1 and page.count(end_marker) == 1, f'{page_name}: the markers of {list_id} must appear once.'
	content_start = page.index('-->', start) + len('-->')
	# the list is indented like its start marker
	line_start = page.rfind('\n', 0, start) + 1
	indent = page[line_start:start]
	assert indent.strip() == '', f'{page_name}: the start marker of {list_id} must be alone on its line.'
	content = ''.join('\n' + indent + line for line in lines)
	return page[:content_start] + content + '\n' + indent + page[end:]

def main():
	list_lines = {}
	for list_id, data_file in LIST_DATA.items():
		with open(os.path.join(PATH_TO_DATA, data_file), 'r', encoding='utf-8') as json_file:
			json_data = json.load(json_file)
		list_lines[list_id] = [line for item in json_data for line in ITEM_BUILDERS[list_id](item)]

	for page_name, list_ids in PAGE_LISTS.items():
		page_path = os.path.join(PATH_TO_WEB, page_name)
		with open(page_path, 'r', encoding='utf-8') as page_file:
			page = page_file.read()
		new_page = page
		for list_id in list_ids:
			new_page = fill_list(new_page, page_name, list_id, list_lines[list_id])
		if new_page == page:
			print(f"{page_name}: lists already up to date.")
			continue
		with open(page_path, 'w', encoding='utf-8') as page_file:
			page_file.write(new_page)
		print(f"{page_name}: updated {', '.join(list_ids)}.")

if __name__ == '__main__':
	main()
